const upsertMarketplaceSettings = `-- name: UpsertMarketplaceSettings :one
INSERT INTO marketplace_settings (
  company_id, is_listed, visibility_status, public_description, published_at
) VALUES (
  $1, $2, $3,
  $4, $5
)
ON CONFLICT (company_id) DO UPDATE SET
  is_listed = EXCLUDED.is_listed,
  visibility_status = EXCLUDED.visibility_status,
  public_description = EXCLUDED.public_description,
  published_at = COALESCE(EXCLUDED.published_at, marketplace_settings.published_at)
RETURNING company_id, is_listed, visibility_status, public_description, published_at, created_at, updated_at
`

type UpsertMarketplaceSettingsParams struct {
	CompanyID         uuid.UUID  `json:"company_id"`
	IsListed          bool       `json:"is_listed"`
	VisibilityStatus  string     `json:"visibility_status"`
	PublicDescription *string    `json:"public_description"`
	PublishedAt       *time.Time `json:"published_at"`
}

func (q *Queries) UpsertMarketplaceSettings(ctx context.Context, arg UpsertMarketplaceSettingsParams) (MarketplaceSetting, error) {
	row := q.db.QueryRow(ctx, upsertMarketplaceSettings,
		arg.CompanyID,
		arg.IsListed,
		arg.VisibilityStatus,
		arg.PublicDescription,
		arg.PublishedAt,
	)
	var i MarketplaceSetting
	err := row.Scan(
		&i.CompanyID,
		&i.IsListed,
		&i.VisibilityStatus,
		&i.PublicDescription,
		&i.PublishedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
